"use client";
import { useEffect, useRef, useState } from "react";
import QRCode from "qrcode";
export function StoreQr({ url, name, logo }: { url: string | null; name: string; logo?: string | null }) {
  const canvas = useRef<HTMLCanvasElement>(null); const [generated, setGenerated] = useState(false); const [ready, setReady] = useState(false); const [error, setError] = useState(""); const [copied, setCopied] = useState(false);
  useEffect(() => { setGenerated(false); setReady(false); setError(""); }, [url]);
  useEffect(() => { let active = true; if (!generated || !canvas.current || !url) return; QRCode.toCanvas(canvas.current, url, { width: 1200, margin: 5, errorCorrectionLevel: "H", color: { dark: "#10251d", light: "#FFFFFF" } }).then(() => { if (active) setReady(true); }).catch(() => { if (active) setError("Could not generate QR."); }); return () => { active = false; }; }, [generated, url]);
  async function copyLink() { if (!url) return; try { await navigator.clipboard.writeText(url); setCopied(true); window.setTimeout(() => setCopied(false), 1800); } catch { setError("Could not copy the store link."); } }
  function downloadPng() { if (!canvas.current) return; const a = document.createElement("a"); a.href = canvas.current.toDataURL("image/png"); a.download = `${name.toLowerCase().replace(/[^a-z0-9]+/g, "-") || "joro-store"}-qr.png`; a.click(); }
  async function downloadSvg() { if (!url) return; try { const svg = await QRCode.toString(url, { type: "svg", margin: 5, errorCorrectionLevel: "H", color: { dark: "#10251d", light: "#FFFFFF" } }); const blob = new Blob([svg], { type: "image/svg+xml" }); const a = document.createElement("a"); a.href = URL.createObjectURL(blob); a.download = `${name.toLowerCase().replace(/[^a-z0-9]+/g, "-") || "joro-store"}-qr.svg`; a.click(); URL.revokeObjectURL(a.href); } catch { setError("Could not export SVG."); } }
  function printQr() {
    if (!canvas.current || !ready) return;
    const printWindow = window.open("", "_blank");
    if (!printWindow) return setError("Allow pop-ups to print the QR.");
    printWindow.opener = null;
    printWindow.document.title = `${name} QR`;
    const img = printWindow.document.createElement("img");
    img.style.cssText = "display:block;width:70mm;margin:20mm auto";
    img.alt = `QR code for ${name}`;
    const caption = printWindow.document.createElement("p");
    caption.style.cssText = "text-align:center;font:16px sans-serif";
    caption.textContent = `Scan to visit ${name}`;
    img.onload = () => { printWindow.focus(); printWindow.print(); };
    img.src = canvas.current.toDataURL("image/png");
    printWindow.document.body.replaceChildren(img, caption);
  }
  return <section className="mt-8 overflow-hidden rounded-3xl border border-emerald-100 bg-white shadow-[0_18px_50px_rgba(6,61,41,0.10)]"><div className="bg-brand-dark px-6 py-5 text-white sm:px-8"><p className="text-xs font-bold uppercase tracking-[0.2em] text-brand-primary">Share your storefront</p><h2 className="mt-1 text-2xl font-black">Store QR code</h2><p className="mt-1 text-sm text-white/70">Print or share this code so customers can visit your public store.</p></div>{url ? <div className="p-6 sm:p-8">{!generated ? <div className="rounded-2xl border border-dashed border-emerald-200 bg-emerald-50/50 p-8 text-center"><div className="mx-auto flex h-16 w-16 items-center justify-center rounded-2xl bg-brand-primary text-2xl font-black text-brand-dark">QR</div><h3 className="mt-4 text-xl font-black text-darkText">Ready to generate</h3><p className="mt-2 text-sm text-darkText/65">Create a high-contrast QR for your saved public storefront.</p><button type="button" onClick={() => setGenerated(true)} className="mt-5 rounded-xl bg-brand-primary px-5 py-3 font-bold text-brand-dark">Generate QR Code</button></div> : <div className="grid gap-8 lg:grid-cols-[minmax(0,1fr)_minmax(0,1.1fr)] lg:items-center"><div className="text-center"><div className="mx-auto flex aspect-square w-full max-w-[310px] items-center justify-center rounded-2xl border border-emerald-100 bg-white p-3 shadow-inner"><canvas ref={canvas} aria-label={`QR code for ${name}`} className="h-full w-full" /></div><p className="mt-4 text-sm font-semibold text-darkText">Scan to visit our store</p></div><div><div className="flex items-center gap-4">{logo ? <img src={logo} alt="" className="h-16 w-16 rounded-2xl border border-borderGray object-cover" /> : <div className="flex h-16 w-16 items-center justify-center rounded-2xl bg-brand-primary text-lg font-black text-brand-dark">{name.slice(0, 2).toUpperCase()}</div>}<div><h3 className="text-xl font-black text-darkText">{name}</h3><p className="mt-1 break-all text-sm text-darkText/60">{url}</p></div></div><div className="mt-6 grid gap-3 sm:grid-cols-2"><button disabled={!ready} onClick={downloadPng} className="rounded-xl bg-brand-primary px-4 py-3 font-bold text-brand-dark disabled:opacity-50">Download PNG</button><button disabled={!ready} onClick={() => void downloadSvg()} className="rounded-xl border border-emerald-200 px-4 py-3 font-bold text-brand-link disabled:opacity-50">Download SVG</button><button disabled={!ready} onClick={printQr} className="rounded-xl border border-emerald-200 px-4 py-3 font-bold text-brand-link disabled:opacity-50">Print QR</button><button disabled={!ready} onClick={() => void copyLink()} className="rounded-xl border border-emerald-200 px-4 py-3 font-bold text-brand-link disabled:opacity-50">{copied ? "Copied" : "Copy Store Link"}</button><a href={url} target="_blank" rel="noreferrer" className="rounded-xl bg-brand-dark px-4 py-3 text-center font-bold text-white sm:col-span-2">Visit Store</a></div><p role="alert" className="mt-3 min-h-5 text-sm text-red-700">{error}</p></div></div>}</div> : <div className="p-8 text-center"><p className="font-bold text-darkText">QR code is waiting for a public HTTPS domain.</p><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-darkText/65">Configure <code>NEXT_PUBLIC_APP_URL</code> or <code>NEXTAUTH_URL</code> with your live HTTPS domain, then restart the app. Localhost QR codes are intentionally not generated.</p></div>}</section>;
}
